prompt:card_catalog[post_hoc].description:
Building blocks (reused object shapes):
  ProjectProfilePatchOperation = { op*: "add" | "replace" | "remove", path*: string (For a confirmed hard fact use "/facts/<key>" with op "add" (works for both new and changed values). For an uncertain inference use "/assumptions/<key>". Known fact keys and values: main_use: residential|office|lodging|assembly|healthcare|agriculture|manufacturing|storage|other; building_class: GK1|GK2|GK3|GK4|GK5; escape_level: <=7m|7-11m|11-22m|>22m; existing_or_new: existing|new_build|extension_and_conversion; land_designation: building_land|traffic_area|open_land|core|mixed; development_pattern: open|semi_detached|closed; safety_category: low|medium|high; existing_age: <10|10-30|30-50|>50; storeys_above_ground / storeys_below_ground / bed_count / unit_count: number; plot_boundary / building_line / protection_zone / deviating_development_plan: boolean; high_rise_details: free text), value: Any (The PLAIN value only (e.g. "GK4", 3, true) — never wrap it in an object; the app adds provenance metadata when the user accepts.) }
  ProjectProfilePatchPreviewItem = { label*: string, before*: string, after*: string }
  CalculationStep = { label*: string (What this step computes, e.g. 'Netto-Grundfläche', 'Geschossflächenzahl'; non-empty), operation*: "sum" | "product" | "quotient" | "percent_of" | "percent_ratio" (Which of the five shapes this step is: 'sum' (Σ factor × value), 'product' (Π value), 'quotient' (first ÷ second), 'percent_of' (second, as a percentage, OF first), 'percent_ratio' (first ÷ second × 100, a percentage)), operands*: [CalculationOperand] (The numbers going in, in the order they are read. 'quotient', 'percent_of' and 'percent_ratio' take EXACTLY two; non-empty), unit: string (Unit of THIS step's result, e.g. 'cm', 'm²', 'W/(m²K)'; omit for a dimensionless ratio like a GFZ. Ignored on 'percent_ratio', whose result is always a percentage) }
  CalculationLimit = { comparator*: "<=" | ">=" | "between" (How the result must relate to the bound: at most, at least, or inside a range), value*: number (The bound. With 'between', this is the LOWER bound), upper: number (With 'between': the upper bound of the range. Otherwise omit), label: string (Optional name of the limit, e.g. 'Netto-Grundfläche'; omit when the reference says it), reference: NormReference (Where the bound is written. Never invent one) }
  NormReference = { document*: string (Regulation name, e.g. 'OIB-Richtlinie 2', 'ÖNORM B 1600'; non-empty), section: string (Clause/table, e.g. 'Pkt. 5.1.1', 'Tabelle 1b'), edition: string (Edition/year, e.g. 'Ausgabe Mai 2023'), excerpt: string (Literal quoted sentence grounding the value (<= ~200 chars)) }
  UValueFormula = { name*: "u_value", component*: "external_wall" | "roof_or_ceiling_to_outside_air" | "floor_over_outside_air" (Which component: 'external_wall', 'roof_or_ceiling_to_outside_air' (a ceiling or roof slope, slopes over 60° are walls), 'floor_over_outside_air' (a ceiling over a passage or parking deck)), measure: "new_build" | "renovation" | "major_renovation" ('new_build' (Pkt. 4.4.1), 'renovation' (single measures or a renewed component, Pkt. 4.5) or 'major_renovation' (a größere Renovierung, held to the energy figures of Pkt. 4.3, which this card does not judge). Read it from the project context (existing_or_new); null when it is not known, and the card then says it cannot judge), layers*: [UValueLayer] (The layers, inside to outside; non-empty) }
  StairStepRuleFormula = { name*: "stair_step_rule", stair_type*: "main" | "dwelling" | "secondary" (The row of Tabelle 3: 'main' (Haupttreppe, not a Wohnungstreppe), 'dwelling' (Wohnungstreppe, inside one dwelling), 'secondary' (Nebentreppe)), riser*: FormulaInput (Stufenhöhe (Steigung) s in cm), going*: FormulaInput (Stufenauftritt a in cm) }
  EscapeRouteLengthFormula = { name*: "escape_route_length", start*: "room" | "dwelling_entrance" (Where the route starts: 'room', the most remote point of the room (Pkt. 5.1.1); 'dwelling_entrance', the Wohnungseingangstüre, for a dwelling over at most two storeys whose route leads to a Treppenhaus or Außentreppe (Pkt. 5.1.2, cases b and c)), segments*: [EscapeRouteSegment] (The legs in walking order; non-empty) }
  DaylightRatioFormula = { name*: "daylight_ratio", opening_area*: FormulaInput (Lichteintrittsfläche: the Architekturlichte of the room's windows and skylights, in m²), floor_area*: FormulaInput (Bodenfläche of the room in m²), room_depth*: FormulaInput (Raumtiefe in m, measured from the façade with the openings), overhang_depth*: FormulaInput (Depth of an overhang of the same building that shades the openings (balcony, eaves, loggia), from the façade, in m. 0 when there is none) }
  SectionStorey = { label*: string (Storey label, e.g. 'EG', '1.OG', 'KG'; non-empty), height_m*: number (Clear storey height in metres (drawn to scale); > 0), below_grade: boolean (True for basements/underground storeys; default false) }
  SectionMarker = { label*: string (What the line marks, e.g. 'Fluchtniveau', 'GK4-Grenze'; non-empty), height_m*: number (Height above ground datum in metres), kind: "escape_level" | "threshold" | "reference" (Styling role; default "reference") }
  DimensionCheck = { label*: string (What is measured, e.g. 'lichte Durchgangsbreite'; non-empty), value: number (Actual measurement (drawn); null if unknown), required: number (OIB limit for this dimension), unit: string (Unit for both value and required, e.g. 'cm', 'm', '%'; default "cm"), comparator: "<=" | ">=" (How actual must relate to required), status*: "pass" | "fail" | "warning" | "needs_input" (Verdict for this dimension), provenance: "declared" | "computed" | "inferred" (Where `value` came from, copied from the ifc_measure answer's own provenance: 'declared' (the IFC file states it), 'computed' (we measured it off the geometry), 'inferred' (a heuristic, offered for confirmation). Leave null when the number did not come from the model at all — a figure the user typed, or one taken from the Bestimmung. NEVER guess it: labelling our own measurement 'declared' turns our tolerance into the architect's claim.), tolerance: number (The ± band on `value`, in the SAME unit — copied from the ifc_measure answer. Only meaningful with provenance 'computed': a declared figure is the file's statement and has no band of ours. A measured dimension without its band reads as exact, and the band is what decides whether 2.49 m clears a 2.50 m minimum.; >= 0), missing: string (With status 'needs_input': what the export does not provide and WHAT TO CHANGE IN THE CAD to make it answerable — copied verbatim from the ifc_measure answer's missing.remedy. This is the sentence the architect acts on, and a card that shows an empty slot instead of it turns a finding about the export into a blank the reader reads as a fact about the building.) }
  SetbackSide = { side*: "front" | "back" | "left" | "right" (Which edge), required_m*: number (Required setback in metres (OIB/Bauordnung)), actual_m: number (Actual distance in metres; null if unknown), status*: "pass" | "fail" | "warning" | "needs_input" (Verdict for this side) }
  EgressSegment = { label*: string (Segment label, e.g. 'Raum → Gang', 'Gang → Treppenhaus'; non-empty), length_m*: number (Run length in metres (drawn to scale); > 0), turn: "straight" | "left" | "right" (Turn AFTER this run; default "straight") }
  Obstruction = { distance_m*: number (Horizontal distance from the window in metres; > 0), height_m*: number (Height of the obstruction above the window sill in metres), label*: string (What it is, e.g. 'Gegenüberliegendes Gebäude'; non-empty) }
  StagingAreaPlan = { width*: DimensionCheck (Aufstellfläche width (m)), length*: DimensionCheck (Aufstellfläche length (m)), distance_to_facade: DimensionCheck (Distance to the facade (m)) }
  CalculationOperand = { label*: string (What this number IS, e.g. 'Steigung', 'Bruttogeschossfläche', 'Grundfläche'. Empty ONLY for a bare constant that names itself, such as the 100 of a percentage — everything a reader has to look up needs its name under it), value: number (The number itself. Leave null when it is not known — the renderer then shows the step as undecidable instead of a result, which is the honest outcome. Must be null when `step` is set), unit: string (Unit of this operand, e.g. 'cm', 'm²', 'MJ'; omit for a bare count or a ratio), factor: number (Only on a 'sum': the RULE's own multiplier for this term, e.g. 2 for a two-sided Abstand. Negative subtracts the term. Omit for a plain +1 — never use it to smuggle a second measured quantity in, which is what a 'product' step is for), step: integer (Instead of a value: the 1-based index of an EARLIER step whose result this operand is. Must point strictly backwards. With this set, leave value, unit, provenance and tolerance null — the renderer takes them from the step it names), provenance: "declared" | "computed" | "inferred" (Where `value` came from, copied from the ifc_measure answer's own provenance: 'declared' (the IFC file states it), 'computed' (we measured it off the geometry), 'inferred' (a heuristic). Leave null for a figure the user typed or a limit read out of the Bestimmung. NEVER guess it), tolerance: number (The ± band on `value`, in the SAME unit — copied from the ifc_measure answer, and only meaningful with provenance 'computed'. The renderer propagates it through every following step, so this is what decides whether the derived result is genuinely on one side of a limit; >= 0), source: string (Optional half-line naming WHERE the figure is written down, e.g. 'Einreichplan, Schnitt A-A' or 'Bebauungsplan PD 8123'. Revealed when the reader expands the derivation's sources) }
  UValueLayer = { label*: string (The layer's material, never its thickness: 'Mineralwolle', 'Stahlbeton'; non-empty), thickness*: FormulaInput (Thickness d in cm), conductivity*: FormulaInput (Thermal conductivity λ in W/(m·K), the design value) }
  FormulaInput = { value: number (The value as the SOURCE gives it, in the unit the field names. Null when it is not known: the card then says it cannot judge, and the reader may type an assumption of their own), editable: boolean (Whether the reader may change it for a what-if. False only for a figure that is not a design choice in this question (an existing wall's thickness the question does not touch); default true), min: number (Lowest plausible value, in the field's unit; omit if none), max: number (Highest plausible value, in the field's unit; omit if none), step: number (The increment the arrow keys move by, e.g. 0.5 for cm, 0.001 for λ; > 0), provenance: "declared" | "computed" | "inferred" (Where `value` came from, copied from the ifc_measure answer: 'declared', 'computed', 'inferred'. Null for a figure the user stated or one read from a document or a norm), source: string (Half a line naming WHERE the value is written: 'Einreichplan, Schnitt A-A', 'Ihre Angabe', 'Produktdatenblatt'. Shown beside the input, so the reader knows what they are changing), reference: NormReference (When the value is a norm's own figure (a tabulated λ): where it is written. Never invent one) }
  EscapeRouteSegment = { label*: string (The leg, by its ends, never its length: 'Raum → Gang'; non-empty), length*: FormulaInput (Length in m) }

